LSE 0 END * 0.15 + CASE WHEN m.total_disk_spill > 0 THEN 100 ELSE 0 END * 0.15 + (100.0 - LEAST(100, COALESCE((m.total_cpu_time / 1000000.0 * 100.0 / NULLIF(m.total_run_time, 0)), 100))) * 0.10 + COALESCE((m.total_delay * 100.0 / NULLIF(m.total_duration, 0)), 0) * 0.05 + COALESCE(((m.total_ser + m.total_deser) * 100.0 / NULLIF(m.total_duration, 0)), 0) * 0.05 + COALESCE((m.total_get_res * 100.0 / NULLIF(m.total_duration, 0)), 0) * 0.05)), diagnosis_info = json_array(json_object('dimension', 'GC Impact', 'score', CAST(greatest(0, 100 - COALESCE((m.total_gc * 100.0 / NULLIF(m.total_duration, 0)), 0)) AS INTEGER)), json_object('dimension', 'Shuffle Write Impact', 'score', CAST(greatest(0, 100 - COALESCE((m.total_sw_time / 1000000.0 * 100.0 / NULLIF(m.total_duration, 0)), 0)) AS INTEGER)), json_object('dimension', 'Shuffle Read Blocked', 'score', CAST(greatest(0, 100 - COALESCE((m.total_fetch_wait / 1000000.0 * 100.0 / NULLIF(m.total_duration, 0)), 0)) AS INTEGER)), json_object('dimension', 'I/O Wait', 'score', CAST(LEAST(100, COALESCE((m.total_cpu_time / 1000000.0 * 100.0 / NULLIF(m.total_run_time, 0)), 100)) AS INTEGER)), json_object('dimension', 'Serialization Impact', 'score', CAST(greatest(0, 100 - COALESCE(((m.total_ser + m.total_deser) * 100.0 / NULLIF(m.total_duration, 0)), 0)) AS INTEGER)), json_object('dimension', 'Result Fetching', 'score', CAST(greatest(0, 100 - COALESCE((m.total_get_res * 100.0 / NULLIF(m.total_duration, 0)), 0)) AS INTEGER)), json_object('dimension', 'Scheduler Delay Impact', 'score', CAST(greatest(0, 100 - COALESCE((m.total_delay * 100.0 / NULLIF(m.total_duration, 0)), 0)) AS INTEGER)), json_object('dimension', 'Data Skew', 'score', CAST(greatest(0, 100 - CASE WHEN m.p50 > 0 THEN LEAST(100, (m.max_dur * 1.0 / m.p50 - 1) * 50) ELSE 0 END) AS INTEGER)), json_object('dimension', 'Disk Spill', 'score', CASE WHEN m.total_disk_spill > 0 THEN 0 ELSE 100 END)) FROM (
) m, (
) m_loc WHERE gold_stages.app_id = m.app_id AND gold_stages.stage_id = m.stage_id AND gold_stages.attempt_id = m.attempt_id AND m.app_id = m_loc.app_id AND m.stage_id = m_loc.stage_id AND m.attempt_id = m_loc.attempt_id AND gold_stages.app_id = #{appId}

