SELECT executor_id as executorId, count(*) as taskCount, sum(executor_deserialize_time) as executorDeserializeTime, sum(duration) as duration, sum(gc_time) as gcTime, sum(result_serialization_time) as resultSerializationTime, sum(getting_result_time) as gettingResultTime, sum(scheduler_delay) as schedulerDelay, max(peak_execution_memory) as peakExecutionMemory, sum(memory_bytes_spilled) as memoryBytesSpilled, sum(disk_bytes_spilled) as diskBytesSpilled, sum(input_bytes) as inputBytes, sum(input_records) as inputRecords, sum(output_bytes) as outputBytes, sum(output_records) as outputRecords, sum(shuffle_read_bytes) as shuffleReadBytes, sum(shuffle_read_records) as shuffleReadRecords, sum(shuffle_write_bytes) as shuffleWriteBytes, sum(shuffle_write_records) as shuffleWriteRecords, sum(shuffle_write_time) as shuffleWriteTime FROM gold_tasks WHERE app_id = #{appId} AND stage_id = #{stageId}
AND attempt_id = #{attemptId}
GROUP BY executor_id ORDER BY executor_id ASC
